public void generateGraph(Graph<V,E> target, Map<String, V> resultMap) {
    // Create a map to store the nodes in the target graph
    Map<String, V> nodeMap = new HashMap<>();

    // Iterate through the resultMap and add each node to the target graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        // Add the node to the target graph
        target.addVertex(entry.getValue());
        // Add the node to the map
        nodeMap.put(entry.getKey(), entry.getValue());
    }

    // Now iterate through the resultMap again and connect each node to its neighbors in the target graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        // Get the current node
        V currentNode = entry.getValue();
        // Get the neighbors of the current node
        List<String> neighborNames = resultMap.get(entry.getKey());
        // Iterate through the neighbors
        for (String neighborName : neighborNames) {
            // Get the corresponding node in the target graph
            V neighbor = nodeMap.get(neighborName);
            // Create an edge between the current node and its neighbor
            target.addEdge(currentNode, neighbor);
        }
    }
}
